#!/usr/bin/env node
// Writes the head block, the main navigation and the footer links (tools/site-nav.mjs) into every hand-written page.
//
//   node tools/build-nav.mjs           # rewrite the head block (siteHead), <nav class="site-nav"> and <p class="site-footer__links">
//   node tools/build-nav.mjs --check   # report the pages that are out of date and exit 1, writes nothing
//
// The head block is found by its marker, the head script <script data-pw-head> (and the lines siteHead puts before
// it). The docs pages are generated by tools/build-docs.mjs, which takes the same navigation from tools/site-nav.mjs.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { siteNav, siteFooterLinks, siteHead, NAV_PATTERN, FOOTER_PATTERN, HEAD_PATTERN } from './site-nav.mjs';
import { computeHashes, stampHtml } from './stamp-assets.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Hand-written pages: file, path to the site root, page key for aria-current.
export const HAND_PAGES = [
  ['index.html', '', 'home'],
  ['configurator/index.html', '../', 'configurator'],
  ['roadmap/index.html', '../', 'roadmap'],
  ['changelog/index.html', '../', 'changelog'],
  ['impressum/index.html', '../', 'impressum'],
  ['datenschutz/index.html', '../', 'datenschutz'],
  ['convert/index.html', '../', 'convert'],
  ['addons/index.html', '../', 'addons'],
  ['addons/just-more-parts/index.html', '../../', 'addons-sub'],
  ['brand/index.html', '../', 'brand'],
];

/** Full-window app pages without the site navigation and footer (the FPV simulator), reached from the configurator. */
export const APP_PAGES = ['sim/index.html'];

/** A page with the current navigation and footer links (options as for siteNav). */
export function withNav(html, prefix, current, file, options = {}) {
  if (!NAV_PATTERN.test(html)) throw new Error(`${file}: <nav class="site-nav"> not found`);
  if (!FOOTER_PATTERN.test(html)) throw new Error(`${file}: <p class="site-footer__links"> not found`);
  return html.replace(NAV_PATTERN, () => siteNav(prefix, current, options)).replace(FOOTER_PATTERN, () => siteFooterLinks(prefix, current, options));
}

/** A page with the current head block (options as for siteHead). */
export function withHead(html, prefix, file, options = {}) {
  if (!HEAD_PATTERN.test(html)) throw new Error(`${file}: head script <script data-pw-head> not found`);
  return html.replace(HEAD_PATTERN, () => siteHead(prefix, file.replace(/index\.html$/, ''), options));
}

/** A hand-written page as this script writes it. */
export function buildPage(html, prefix, current, file, options = {}, hashes = computeHashes()) {
  return stampHtml(file, withHead(withNav(html, prefix, current, file, options), prefix, file, options), hashes);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const hashes = computeHashes();
  const stale = [];
  for (const [file, prefix, current] of HAND_PAGES) {
    const target = path.join(ROOT, file);
    const html = fs.readFileSync(target, 'utf8');
    const next = buildPage(html, prefix, current, file, {}, hashes);
    if (next === html) continue;
    stale.push(file);
    if (!check) fs.writeFileSync(target, next);
  }
  if (check) {
    if (stale.length) {
      console.log(`head block, navigation or footer links out of date in: ${stale.join(', ')} – run node tools/build-nav.mjs`);
      process.exit(1);
    }
    console.log('head block, navigation and footer links: every hand-written page is up to date');
  } else {
    console.log(stale.length ? `head block, navigation and footer links written into ${stale.join(', ')}` : 'head block, navigation and footer links: nothing to do');
  }
}
